using UnityEngine;
using UnityEngine.UI;
[DisallowMultipleComponent] public sealed class FirstConveyorViewSwitch : MonoBehaviour {
 [SerializeField] Camera firstCamera,topCamera,leftCamera,rightCamera,pusherCamera,containerACamera,containerBCamera,containerCCamera,containerAArmCamera,containerBArmCamera,containerCArmCamera;
 [SerializeField] Camera[] otherCameras;
 [SerializeField] Button areaButton,backButton,leftButton,rightButton,pusherButton,containerAButton,containerBButton,containerCButton,containerAArmButton,containerBArmButton,containerCArmButton;
 [SerializeField] Canvas hudCanvas;
 Camera[] cameras;bool[] states,listeners;int[] displays;int display;Camera currentCamera;
 void OnEnable(){if(!Application.isPlaying)return;if(firstCamera==null||topCamera==null||areaButton==null||backButton==null){Debug.LogError("카메라 시점 전환 연결이 필요합니다.",this);return;}display=firstCamera.targetDisplay;var list=new System.Collections.Generic.List<Camera>{firstCamera,topCamera};if(containerAArmCamera!=null)list.Add(containerAArmCamera);if(containerBArmCamera!=null)list.Add(containerBArmCamera);if(containerCArmCamera!=null)list.Add(containerCArmCamera);if(containerBCamera!=null)list.Add(containerBCamera);if(containerCCamera!=null)list.Add(containerCCamera);if(containerACamera!=null)list.Add(containerACamera);if(pusherCamera!=null)list.Add(pusherCamera);if(leftCamera!=null)list.Add(leftCamera);if(rightCamera!=null)list.Add(rightCamera);if(otherCameras!=null)foreach(var c in otherCameras)if(c!=null&&!list.Contains(c))list.Add(c);cameras=list.ToArray();states=new bool[cameras.Length];listeners=new bool[cameras.Length];displays=new int[cameras.Length];for(int i=0;i<cameras.Length;i++){var c=cameras[i];states[i]=c.enabled;displays[i]=c.targetDisplay;var l=c.GetComponent<AudioListener>();listeners[i]=l!=null&&l.enabled;}areaButton.onClick.AddListener(ShowTop);backButton.onClick.AddListener(GoBack);if(containerCArmButton!=null)containerCArmButton.onClick.AddListener(ShowContainerCArm);if(containerBArmButton!=null)containerBArmButton.onClick.AddListener(ShowContainerBArm);if(containerAArmButton!=null)containerAArmButton.onClick.AddListener(ShowContainerAArm);if(containerBButton!=null)containerBButton.onClick.AddListener(ShowContainerB);if(containerCButton!=null)containerCButton.onClick.AddListener(ShowContainerC);if(containerAButton!=null)containerAButton.onClick.AddListener(ShowContainerA);if(pusherButton!=null)pusherButton.onClick.AddListener(ShowPusher);if(leftButton!=null)leftButton.onClick.AddListener(ShowLeft);if(rightButton!=null)rightButton.onClick.AddListener(ShowRight);ShowFirst();}
 public void ShowFirst(){Select(firstCamera);} public void ShowTop(){Select(topCamera);}
 public void ShowContainerB(){Select(containerBCamera);} public void ShowContainerC(){Select(containerCCamera);}
 public void ShowContainerCArm(){Select(containerCArmCamera);} public void ShowContainerBArm(){Select(containerBArmCamera);} public void ShowContainerAArm(){Select(containerAArmCamera);}
 public void GoBack(){if(currentCamera==containerAArmCamera&&containerAArmCamera!=null)ShowContainerA();else if(currentCamera==containerBArmCamera&&containerBArmCamera!=null)ShowContainerB();else if(currentCamera==containerCArmCamera&&containerCArmCamera!=null)ShowContainerC();else ShowFirst();}
 public void ShowContainerA(){Select(containerACamera);}
 public void ShowPusher(){Select(pusherCamera);}
 public void ShowLeft(){Select(leftCamera);} public void ShowRight(){Select(rightCamera);}
 void Select(Camera selected){if(cameras==null||selected==null)return;currentCamera=selected;bool top=selected!=firstCamera;selected.targetDisplay=display;foreach(var c in cameras){c.enabled=c==selected;var l=c.GetComponent<AudioListener>();if(l!=null)l.enabled=c==selected;}areaButton.gameObject.SetActive(!top);if(containerCArmButton!=null)containerCArmButton.gameObject.SetActive(selected==containerCCamera);if(containerBArmButton!=null)containerBArmButton.gameObject.SetActive(selected==containerBCamera);if(containerAArmButton!=null)containerAArmButton.gameObject.SetActive(selected==containerACamera);if(containerBButton!=null)containerBButton.gameObject.SetActive(!top);if(containerCButton!=null)containerCButton.gameObject.SetActive(!top);if(containerAButton!=null)containerAButton.gameObject.SetActive(!top);if(pusherButton!=null)pusherButton.gameObject.SetActive(!top);backButton.gameObject.SetActive(top);if(leftButton!=null){leftButton.gameObject.SetActive(top&&selected!=pusherCamera&&selected!=containerACamera&&selected!=containerBCamera&&selected!=containerCCamera&&selected!=containerAArmCamera&&selected!=containerBArmCamera&&selected!=containerCArmCamera);leftButton.interactable=selected!=leftCamera;}if(rightButton!=null){rightButton.gameObject.SetActive(top&&selected!=pusherCamera&&selected!=containerACamera&&selected!=containerBCamera&&selected!=containerCCamera&&selected!=containerAArmCamera&&selected!=containerBArmCamera&&selected!=containerCArmCamera);rightButton.interactable=selected!=rightCamera;}GetComponent<Canvas>().targetDisplay=display;if(hudCanvas!=null)hudCanvas.targetDisplay=display;}
 void OnDisable(){if(containerCArmButton!=null)containerCArmButton.onClick.RemoveListener(ShowContainerCArm);if(containerBArmButton!=null)containerBArmButton.onClick.RemoveListener(ShowContainerBArm);if(containerAArmButton!=null)containerAArmButton.onClick.RemoveListener(ShowContainerAArm);if(containerBButton!=null)containerBButton.onClick.RemoveListener(ShowContainerB);if(containerCButton!=null)containerCButton.onClick.RemoveListener(ShowContainerC);if(containerAButton!=null)containerAButton.onClick.RemoveListener(ShowContainerA);if(pusherButton!=null)pusherButton.onClick.RemoveListener(ShowPusher);if(leftButton!=null)leftButton.onClick.RemoveListener(ShowLeft);if(rightButton!=null)rightButton.onClick.RemoveListener(ShowRight);if(areaButton!=null)areaButton.onClick.RemoveListener(ShowTop);if(backButton!=null)backButton.onClick.RemoveListener(GoBack);if(cameras==null)return;for(int i=0;i<cameras.Length;i++){var c=cameras[i];if(c==null)continue;c.enabled=states[i];c.targetDisplay=displays[i];var l=c.GetComponent<AudioListener>();if(l!=null)l.enabled=listeners[i];}cameras=null;}
}
